	reg.Start(createRun("g/new", "new"))
	m := Model{jobs: reg.Snapshot()}
	for _, path := range []string{"g/app", "g/new"} {
		if !m.busy(path) {
			t.Errorf("busy(%q) = false while its run is running", path)
		}
	}
